"""Build a standalone, searchable review catalogue from glyph research JSON."""
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'research/glyphs'
data = json.loads((ROOT / 'identifications.json').read_text())
glyphs = data['glyphs']
assert len({g['id'] for g in glyphs}) == len(glyphs)
preview_dir = ROOT / 'previews'
preview_dir.mkdir(exist_ok=True)
for glyph in glyphs:
    svg = (ROOT / 'build/glyphs' / f"{glyph['id']}.svg").read_text()
    svg = re.sub(r'<g id="guides".*?</g>', '', svg, flags=re.S)
    (preview_dir / f"{glyph['id']}.svg").write_text(svg)
payload = json.dumps(glyphs, ensure_ascii=False).replace('<', '\\u003c')
page = '''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Dreams — каталог глифов</title><style>
:root{color-scheme:dark;font:15px/1.55 -apple-system,BlinkMacSystemFont,sans-serif;background:#0b100e;color:#dce8df}*{box-sizing:border-box}body{margin:0 auto;max-width:1600px;padding:30px}h1{font-size:34px;letter-spacing:-1px;margin:0}p{color:#a8b9af}a{color:#8dd4a5}header{margin-bottom:24px}.eyebrow{letter-spacing:3px;font-size:12px;color:#78bd94}nav{display:flex;gap:20px;flex-wrap:wrap;margin:15px 0}.controls{position:sticky;top:0;background:#0b100ef5;padding:14px 0;z-index:2;display:flex;gap:12px;align-items:center;flex-wrap:wrap}input,select{font:inherit;background:#16211b;color:#e6f0e9;border:1px solid #385044;border-radius:8px;padding:10px}input{flex:1;min-width:200px}#count{color:#9caf9f}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.card{background:#121b16;border:1px solid #2b3c31;border-radius:12px;overflow:hidden}.card header{padding:14px 16px;margin:0;display:flex;justify-content:space-between;gap:10px;align-items:center}.card h2{margin:0;font-size:19px}.badge{font-size:11px;border:1px solid #49604f;border-radius:20px;padding:3px 8px;color:#c6d8c9}.views{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#2b3c31}.view{background:#060a08;min-width:0}.caption{font-size:11px;letter-spacing:1px;padding:8px;color:#adc0b1}.sample{aspect-ratio:1;display:flex;align-items:center;justify-content:center;background:#000;overflow:hidden}.sample img{height:78%;max-width:92%;object-fit:contain;image-rendering:auto}.restored-frame{aspect-ratio:1;overflow:hidden;background:white;display:flex;align-items:center}.restored{width:100%;flex-shrink:0;background-image:url('references/restored-v5.png');background-size:400% 500%;background-color:white}.body{padding:14px 16px}.identity{display:flex;gap:13px;align-items:center}.character{font-size:42px;min-width:55px;text-align:center;color:#d7f0df}.code{font:12px ui-monospace,monospace;color:#8fa696}.transform{font-size:13px;color:#bacbbf}.next{font-size:13px;border-left:2px solid #578a66;padding-left:10px;margin-top:14px}summary{cursor:pointer;color:#a7d7b5;margin-top:12px;font-size:13px}details{font-size:13px}ul{padding-left:18px}pre{white-space:pre-wrap;word-break:break-word;font-size:12px;color:#b2c5b8}footer{margin:35px 0;color:#93a69a;font-size:13px}.reference{font-size:12px;margin-top:8px}@media(max-width:1250px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:580px){body{padding:16px}.grid{grid-template-columns:1fr}h1{font-size:28px}}
</style><header><div class="eyebrow">DREAMS / GLYPH RESEARCH</div><h1>Каталог восстановленных знаков</h1><p>COUNT форм из фильма. Кадр → гипотеза → реконструкция → проверка.<br>Уверенность относится к идентификации; чистая форма справа ещё требует визуальной сверки.</p><nav><a href="references/simple-forms-v2-proof.png">Новые G21–G28</a><a href="build/proof.png">Проверка собранного шрифта</a><a href="PLAN.md">План работ</a><a href="IDENTIFICATIONS.md">Разбор субагента</a><a href="identifications.json">Данные JSON</a><a href="references/extraction-corrected.png">Извлечение из видео</a><a href="references/film-reference-1.jpg">Референс 1</a><a href="references/film-reference-2.jpg">Референс 2</a><a href="references/film-reference-3.jpg">Референс 3</a></nav></header>
<div class="controls"><input id="search" aria-label="Поиск глифа" placeholder="ID, символ, Unicode, наблюдение…"><select id="confidence" aria-label="Уверенность"><option value="">Все уровни уверенности</option value="confirmed_by_user">Подтверждено пользователем</option><option value="high">Высокая</option><option value="medium">Средняя</option><option value="low">Низкая</option><option value="unidentified">Не определено</option></select><span id="count"></span></div><main class="grid" id="grid"></main><footer>Базовая таблица v5 создана GPT Image. G21–G28 восстановлены вручную в editable SVG по отдельным кадрам. Справа показаны контуры из актуального собранного шрифта. Неизвестные знаки сохраняют ID: сходство с Unicode не доказывает исходную идентичность. Изображения хранятся локально.</footer>
<script>const glyphs=PAYLOAD;
const rowBounds=[0,313,578,834,1085,1402];
const names={confirmed_by_user:'Подтверждено пользователем',high:'Высокая',medium:'Средняя',low:'Низкая',unidentified:'Не определено'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readable=v=>typeof v==='string'?v:JSON.stringify(v,null,2);
function render(){const q=document.querySelector('#search').value.toLowerCase(),c=document.querySelector('#confidence').value;const filtered=glyphs.filter(g=>(!c||g.confidence===c)&&(/^g\\d{2}$/.test(q)?g.id.toLowerCase()===q:JSON.stringify(g).toLowerCase().includes(q)));document.querySelector('#count').textContent=filtered.length+' / '+glyphs.length;document.querySelector('#grid').innerHTML=filtered.map(g=>{const src=g.id==='G17'?'g17-clear.jpg':g.id.toLowerCase()+'-source.png';return `<article class="card" id="${esc(g.id)}"><header><h2>${esc(g.id)}</h2><span class="badge">${esc(names[g.confidence]||g.confidence)}</span></header><div class="views"><div class="view"><div class="caption">КАДР ФИЛЬМА</div><div class="sample"><img src="references/${src}" alt="Референс ${esc(g.id)}"></div></div><div class="view"><div class="caption">КОНТУР В ШРИФТЕ</div><div class="restored-frame"><img src="previews/${esc(g.id)}.svg" alt="Контур ${esc(g.id)}" style="width:100%;height:100%;object-fit:contain"></div></div></div><div class="body"><div class="identity"><div class="character">${esc(g.candidate_character||'?')}</div><div><div>${esc(g.script||'Не определено')}</div><div class="code">${esc(g.unicode||'Без Unicode')}</div><div class="transform">${esc(readable(g.transform))}</div></div></div><div class="next">${esc(g.next_action)}</div><details><summary>Наблюдения и основания</summary><ul>${(g.observations||[]).map(o=>'<li>'+esc(readable(o))+'</li>').join('')}</ul><pre>${esc(readable(g.evidence))}</pre></details><details><summary>Альтернативы</summary><pre>${esc(readable(g.alternatives))}</pre></details><details><summary>Задание на восстановление</summary><pre>${esc(g.reconstruction_prompt)}</pre></details></div></article>`}).join('')};document.querySelector('#search').addEventListener('input',render);document.querySelector('#confidence').addEventListener('change',render);render();</script></html>'''.replace('PAYLOAD', payload).replace('COUNT', str(len(glyphs)))
(ROOT / 'catalog.html').write_text(page)
print(f'Built {ROOT / "catalog.html"}: {len(glyphs)} glyphs')
